<template>
  <div class="learning-matrix" :class="{ 'has-detail': selected || noteRow }">
    <div class="matrix-workspace">
      <header class="matrix-course"><p>{{ courseTitle }}</p><h1>{{ t('learningMatrix.learningOverview', '学习概况') }}</h1>
        <p v-if="!loading && !error" class="matrix-summary">{{ t('learningMatrix.course', '全课') }} {{ rows.length }} {{ t('learningMatrix.knowledgePoints', '个知识点') }} · {{ rows.filter(r => r.activity).length }} {{ t('learningMatrix.withActivity', '点有记录') }} · {{ rows.filter(needsAttention).length }} {{ t('learningMatrix.needAttention', '点待处理') }}</p>
      </header>
      <p v-if="preview" class="matrix-notice" role="status">{{ t('learningMatrix.teacherPreviewCourseKnowledgeOnlyPersonalLearningRecordsAreNotReadOrWritten', '教师预览：展示课程知识，不读取或写入个人学习记录。') }}</p>
      <p v-if="loading" class="matrix-notice" role="status">{{ t('learningMatrix.loadingLearningRecords', '正在读取学习记录…') }}</p>
      <div v-if="error" class="matrix-error" role="alert">{{ error }} <button @click="emit('refresh')">{{ t('learningMatrix.retry', '重试') }}</button></div>
      <section class="matrix-surface" :aria-label="t('learningMatrix.knowledgeLearningMatrix', '知识点学习矩阵')">
        <div class="matrix-toolbar"><h2>{{ t('learningMatrix.learningMatrix', '本章学习矩阵') }}</h2>
          <label class="matrix-search"><Search :size="16" aria-hidden="true" /><input v-model="search" type="search" :placeholder="t('learningMatrix.searchKnowledge', '搜索知识点')" :aria-label="t('learningMatrix.searchKnowledge', '搜索知识点')" /></label>
          <select v-model="section" :aria-label="t('learningMatrix.chapter', '按章节查看')"><option value="">{{ t('learningMatrix.allChapters', '全部章节') }}</option><option v-for="s in sections" :key="s.id" :value="s.id">{{ s.name }}</option></select>
          <nav class="matrix-filters" :aria-label="t('learningMatrix.filterLearningState', '筛选学习状态')"><button v-for="f in filters" :key="f.key" :aria-pressed="filter === f.key" @click="filter = f.key">{{ f.label }}</button></nav>
        </div>
        <div class="matrix-table" role="table" :aria-label="t('learningMatrix.knowledgeAndAttemptHistory', '知识点与历次作答')">
          <div class="matrix-table-heading" role="row"><span role="columnheader">{{ t('learningMatrix.knowledgePoint', '知识点') }}</span><span role="columnheader">{{ t('learningMatrix.attemptHistoryOldestToNewest', '历次作答记录（从早到晚）') }}</span></div>
          <article v-for="row in visibleRows" :key="row.point.knowledge_id" class="matrix-row" role="row">
            <div class="matrix-point" role="rowheader"><button class="point-name" :data-testid="`knowledge-${row.point.knowledge_id}`" @click="emit('knowledge', row.point)">{{ row.point.name }}</button>
              <span class="point-state">{{ error && !row.attempts.length ? t('learningMatrix.recordsUnavailable', '记录暂未完整读取') : stateLabel(row.current) }}</span>
              <div class="point-links"><button v-if="row.attempts.length > recentCount" :data-testid="`expand-${row.point.knowledge_id}`" :aria-expanded="expanded.has(row.point.knowledge_id)" @click="toggle(row.point.knowledge_id)">{{ expanded.has(row.point.knowledge_id) ? t('learningMatrix.showRecent', '收起记录') : t('learningMatrix.all', '全部') + ' ' + row.attempts.length + t('learningMatrix.attempts', '次') }} <ChevronRight :size="12" /></button><span v-else-if="row.attempts.length">{{ row.attempts.length }} {{ t('learningMatrix.attemptsLabel', '次作答') }}</span>
                <button v-if="row.notes.length" :data-testid="`notes-${row.point.knowledge_id}`" @click="showNotes(row)">{{ t('learningMatrix.notes', '笔记') }} {{ row.notes.length }} <ChevronRight :size="12" /></button>
              </div>
            </div>
            <div class="matrix-records" role="cell"><template v-if="row.attempts.length">
              <button v-for="a in displayed(row)" :key="a.id" class="attempt-tile" :class="[a.outcome, { selected: selected?.attempt.id === a.id && selected.row.point.knowledge_id === row.point.knowledge_id }]" :data-attempt-id="a.id" :aria-pressed="selected?.attempt.id === a.id && selected.row.point.knowledge_id === row.point.knowledge_id" @click="selectAttempt(row, a, $event)">
                <span class="attempt-heading">{{ a.questionLabel }} · {{ t('learningMatrix.attempt', '第') }}{{ a.number }}{{ t('learningMatrix.attemptSuffix', '次') }}</span>
                <strong><CircleCheck v-if="a.outcome === 'correct'" :size="15" /><CircleX v-else-if="a.outcome === 'incorrect'" :size="15" /><CircleHelp v-else :size="15" />{{ outcomeLabel(a.outcome) }}</strong>
                <span class="attempt-support">{{ supportLabel(a.support) }}</span><time>{{ date(a.time) }}</time>
              </button>
              <button v-if="expanded.has(row.point.knowledge_id) && row.attempts.length > historyLimit(row)" class="text-action" :data-testid="`more-${row.point.knowledge_id}`" @click="loadMore(row)">{{ t('learningMatrix.moreHistory', '继续展开较早记录') }} · {{ displayed(row).length }} / {{ row.attempts.length }}</button>
            </template><template v-else><span class="matrix-empty-row">{{ error ? t('learningMatrix.recordsUnavailable', '记录暂未完整读取') : t('learningMatrix.noSavedAttempts', '尚无作答记录') }}</span><button v-if="row.practice && !preview" class="text-action" :data-testid="`practice-${row.point.knowledge_id}`" @click="emit('practice', row.practice.nodeId, row.practice.revision)">{{ t('learningMatrix.practice', '练一道题') }} <ChevronRight :size="13" /></button></template></div>
          </article>
          <p v-if="!visibleRows.length && !loading" class="matrix-empty">{{ rows.length ? t('learningMatrix.noMatchingKnowledgePoints', '没有匹配的知识点') : t('learningMatrix.courseKnowledgeIsNotReadyYetYouCanContinueReading', '课程知识树尚未就绪，可先继续阅读。') }}</p>
        </div>
        <footer class="matrix-footer"><div class="matrix-legend"><span><CircleX :size="14" class="legend-wrong" />{{ t('learningMatrix.incorrect', '答错') }}</span><span><CircleCheck :size="14" class="legend-correct" />{{ t('learningMatrix.correct', '答对') }}</span><span><CircleHelp :size="14" />{{ t('learningMatrix.pending', '待确认') }}</span></div><span>{{ t('learningMatrix.total', '共') }} {{ filteredRows.length }} {{ t('learningMatrix.points', '个知识点') }}</span><div class="matrix-pages"><button :disabled="page === 1" :aria-label="t('learningMatrix.previousPoints', '上一页知识点')" @click="page--"><ChevronLeft :size="16" /></button><span>{{ page }} / {{ pages }}</span><button :disabled="page >= pages" :aria-label="t('learningMatrix.nextPoints', '下一页知识点')" @click="page++"><ChevronRight :size="16" /></button></div></footer>
      </section>
      <p class="matrix-policy">{{ t('learningMatrix.colorsDescribeThisCheckOnlyHelpAndHistoryAreRetainedSeparatelyUnassessedDoesNotMeanUnable', '颜色只表示这次检查结果。提示、参考解答及历史记录单独保留；未检查不代表不会。') }}</p>
    </div>
    <aside v-if="selected" class="matrix-detail" data-testid="attempt-detail" @keydown.esc.stop="closeDetail" :aria-label="t('learningMatrix.attemptDetails', '本次作答')">
      <header><h2>{{ t('learningMatrix.attemptDetails', '本次作答') }}</h2><button :aria-label="t('learningMatrix.closeAttemptDetails', '关闭作答详情')" @click="closeDetail"><X :size="19" /></button></header>
      <div class="detail-meta"><span>{{ selected.attempt.questionLabel }} · {{ t('learningMatrix.attempt', '第') }}{{ selected.attempt.number }}{{ t('learningMatrix.attemptSuffix', '次') }}</span><time>{{ date(selected.attempt.time, true) }}</time></div>
      <p class="detail-point">{{ t('learningMatrix.knowledge', '关联知识点：') }}{{ selected.row.point.name }}</p>
      <MarkdownRenderer v-if="prompt(selected.attempt)" class="matrix-question" :content="prompt(selected.attempt)" /><p v-else class="matrix-notice">{{ t('learningMatrix.theExactQuestionRevisionIsUnavailableYourSavedAnswerAndCheckRemainAvailable', '原题版本暂不可读取，保留本次答案与检查记录。') }}</p>
      <h3>{{ t('learningMatrix.myAnswer', '我的答案') }}</h3><pre class="matrix-answer">{{ selected.attempt.answer || t('learningMatrix.noSavedAnswerContent', '未保存答案内容') }}</pre>
      <div class="detail-badges"><span :class="['detail-outcome', selected.attempt.outcome]">{{ outcomeLabel(selected.attempt.outcome) }}</span><span>{{ supportLabel(selected.attempt.support) }}</span></div>
      <p class="matrix-notice">{{ helpDescription(selected.attempt.support) }}</p>
      <template v-if="selected.attempt.feedback"><h3>{{ t('learningMatrix.feedback', '本次反馈') }}</h3><MarkdownRenderer :content="selected.attempt.feedback" /></template>
      <div class="detail-actions"><button data-testid="locate-lecture" @click="emit('lecture', selected.row.point)"><BookOpen :size="16" />{{ t('learningMatrix.openLecture', '定位原文') }}</button><button v-if="selected.row.notes.length" @click="showNotes(selected.row)"><NotebookPen :size="16" />{{ t('learningMatrix.relatedNotes', '关联笔记') }}</button></div>
      <div v-if="selected.attempt.question && selected.attempt.nodeId && !preview" class="detail-practice"><button data-testid="practice-current-question" @click="emit('practice', selected.attempt.nodeId, selected.attempt.questionId)">{{ t('learningMatrix.practiceCurrent', '在题库中练习') }} <ChevronRight :size="16" /></button></div>
      <p v-if="selected.attempt.outcome === 'pending'" class="matrix-notice">{{ t('learningMatrix.gradingOrPerPointAttributionIsUnresolvedNoMasteryConclusionIsMade', '本次结果或逐点归因尚未确认，不据此判断掌握。') }}</p>
    </aside>
    <aside v-else-if="noteRow" class="matrix-detail" :aria-label="t('learningMatrix.relatedNotes', '关联笔记')"><header><h2>{{ t('learningMatrix.relatedNotes', '关联笔记') }}</h2><button :aria-label="t('learningMatrix.closeRelatedNotes', '关闭关联笔记')" @click="closeDetail"><X :size="19" /></button></header><p class="detail-point">{{ noteRow.point.name }}</p><article v-for="n in noteRow.notes" :key="n.id" class="matrix-note"><h3>{{ n.summary || t('learningMatrix.note', '笔记') }}</h3><MarkdownRenderer :content="n.content || n.quote || ''" /><button :data-testid="`open-note-${n.id}`" @click="emit('record', n.id)">{{ t('learningMatrix.openNoteConversation', '打开笔记会话') }} <ChevronRight :size="14" /></button></article></aside>
  </div>
</template>

<script lang="ts">
interface MatrixPresentation { search: string; section: string; filter: string; page: number; expanded: string[]; limits: Record<string, number>; point?: string; attempt?: string; notes?: string }
// Presentation only: no answers or personal learning facts are cached here.
const matrixPresentation = new Map<string, MatrixPresentation>()
</script>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { BookOpen, ChevronLeft, ChevronRight, CircleCheck, CircleHelp, CircleX, NotebookPen, Search, X } from 'lucide-vue-next'
import { activeLocale, t } from '../shared/i18n'
import type { KnowledgeProfileNode } from '../types/knowledge-profile'
import type { MatrixAttempt, MatrixRow, MatrixSupport } from '../utils/learning-matrix'
import MarkdownRenderer from './MarkdownRenderer.vue'
const props = withDefaults(defineProps<{ rows: MatrixRow[]; sections: { id: string; name: string }[]; courseTitle?: string; courseId?: string; viewKey?: string; loading?: boolean; error?: string; preview?: boolean }>(), { courseTitle: '', courseId: '', viewKey: '', loading: false, error: '', preview: false })
const emit = defineEmits<{ (e: 'refresh'): void; (e: 'knowledge', p: KnowledgeProfileNode): void; (e: 'lecture', p: KnowledgeProfileNode): void; (e: 'record', id: string): void; (e: 'practice', node: string, revision: string): void }>()
const search = ref(''), section = ref(''), filter = ref('all'), page = ref(1)
const expanded = ref(new Set<string>()), selected = ref<{ row: MatrixRow; attempt: MatrixAttempt } | null>(null), noteRow = ref<MatrixRow | null>(null)
const historyLimits = ref<Record<string, number>>({})
const presentationKey = computed(() => props.viewKey || props.courseId)
let restoring: MatrixPresentation | undefined = matrixPresentation.get(presentationKey.value)
if (restoring) { search.value = restoring.search; section.value = restoring.section; filter.value = restoring.filter; page.value = restoring.page; expanded.value = new Set(restoring.expanded); historyLimits.value = { ...restoring.limits } }
function savePresentation(key: string) {
  if (!key) return
  matrixPresentation.set(key, { search: search.value, section: section.value, filter: filter.value, page: page.value, expanded: [...expanded.value], limits: { ...historyLimits.value }, point: selected.value?.row.point.knowledge_id, attempt: selected.value?.attempt.id, notes: noteRow.value?.point.knowledge_id })
  if (matrixPresentation.size > 20) matrixPresentation.delete(matrixPresentation.keys().next().value!)
}
onBeforeUnmount(() => savePresentation(presentationKey.value))
const recentCount = 4, pageSize = 8
const filters = computed(() => [{ key: 'all', label: t('learningMatrix.all', '全部') }, { key: 'attention', label: t('learningMatrix.needsAttention', '待处理') }, { key: 'unassessed', label: t('learningMatrix.unchecked', '尚未检查') }])
const needsAttention = (r: MatrixRow) => ['review', 'verify', 'pending'].includes(r.current)
const filteredRows = computed(() => props.rows.filter(r => (!section.value || r.point.section_refs.includes(section.value)) && r.point.name.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()) && (filter.value === 'all' || (filter.value === 'attention' ? needsAttention(r) : !r.attempts.length))))
const pages = computed(() => Math.max(1, Math.ceil(filteredRows.value.length / pageSize)))
const visibleRows = computed(() => filteredRows.value.slice((page.value - 1) * pageSize, page.value * pageSize))
watch([search, section, filter], () => { page.value = 1; closeDetail() })
watch(pages, total => { page.value = Math.min(page.value, total) })
watch(presentationKey, (_key, oldKey) => { savePresentation(oldKey); restoring = undefined; expanded.value = new Set(); historyLimits.value = {}; section.value = ''; search.value = ''; page.value = 1; closeDetail() })
watch(() => props.rows, rows => { if (selected.value && !rows.some(r => r.point.knowledge_id === selected.value?.row.point.knowledge_id && r.attempts.some(a => a.id === selected.value?.attempt.id))) closeDetail(); if (noteRow.value && !rows.some(r => r.point.knowledge_id === noteRow.value?.point.knowledge_id)) closeDetail() })
function toggle(id: string) { const next = new Set(expanded.value); next.has(id) ? next.delete(id) : next.add(id); expanded.value = next }
function historyLimit(row: MatrixRow) { return historyLimits.value[row.point.knowledge_id] || 24 }
function loadMore(row: MatrixRow) { historyLimits.value = { ...historyLimits.value, [row.point.knowledge_id]: historyLimit(row) + 24 } }
function displayed(row: MatrixRow) { return row.attempts.slice(-(expanded.value.has(row.point.knowledge_id) ? historyLimit(row) : recentCount)) }
let detailTrigger: HTMLElement | null = null
function selectAttempt(row: MatrixRow, attempt: MatrixAttempt, event?: MouseEvent) { detailTrigger = event?.currentTarget instanceof HTMLElement ? event.currentTarget : null; selected.value = { row, attempt }; noteRow.value = null }
function showNotes(row: MatrixRow) { noteRow.value = row; selected.value = null }
function closeDetail() { selected.value = null; noteRow.value = null; const trigger = detailTrigger; detailTrigger = null; void nextTick(() => { if (trigger?.isConnected) trigger.focus({ preventScroll: true }) }) }
watch(() => [props.rows, props.loading] as const, ([rows, busy]) => {
  if (!restoring || busy || !rows.length) return
  const previous = restoring; restoring = undefined
  const row = rows.find(r => r.point.knowledge_id === previous.point)
  const attempt = row?.attempts.find(a => a.id === previous.attempt)
  if (row && attempt) selected.value = { row, attempt }
  const notes = rows.find(r => r.point.knowledge_id === previous.notes)
  if (notes) noteRow.value = notes
}, { immediate: true })
function outcomeLabel(value: MatrixAttempt['outcome']) { return value === 'correct' ? t('learningMatrix.correct', '答对') : value === 'incorrect' ? t('learningMatrix.incorrect', '答错') : t('learningMatrix.pending', '待确认') }
function supportLabel(value: MatrixSupport) { return { independent: t('learningMatrix.independent', '独立'), assisted: t('learningMatrix.withHelp', '提示后'), solution_seen: t('learningMatrix.solutionSeen', '参考解答'), unknown: t('learningMatrix.helpUnknown', '帮助情况未确认') }[value] }
function stateLabel(value: MatrixRow['current']) { return { unassessed: t('learningMatrix.unchecked', '尚未检查'), pending: t('learningMatrix.pending', '待确认'), review: t('learningMatrix.recentCheckFailed', '最近检查未通过'), verify: t('learningMatrix.independentCheckNeeded', '待独立验证'), independent_pass: t('learningMatrix.independentPassRecorded', '有独立通过记录') }[value] }
function helpDescription(value: MatrixSupport) { return value === 'independent' ? t('learningMatrix.noSystemHintOrSolutionWasUsedForThisAttempt', '本次未使用系统提示或解答。') : value === 'assisted' ? t('learningMatrix.hintsOrGuidanceWereUsedThisIsAnAssistedAttempt', '本次使用过提示或引导，保留为辅助完成记录。') : value === 'solution_seen' ? t('learningMatrix.theCompleteSolutionWasSeenThisIsNotAnIndependentAttempt', '已查看完整解答，本条记录不标记为独立完成。') : t('learningMatrix.helpMetadataIsIncompleteIndependenceIsNotInferred', '历史记录缺少完整帮助信息，不推断为独立完成。') }
function date(value: string, full = false) { const n = Date.parse(value); return Number.isFinite(n) ? new Date(n).toLocaleString(activeLocale.value === 'zh' ? 'zh-CN' : 'en-US', { month: 'short', day: 'numeric', ...(full ? { hour: '2-digit', minute: '2-digit' } as const : {}) }) : t('learningMatrix.timeUnavailable', '时间未记录') }
function prompt(a: MatrixAttempt) { const q = a.question; return q ? String(q.prompt || q.question_spec?.stimulus?.rendered_text || q.question || '') : '' }
</script>

<style scoped>
