0px,26%) minmax(0,1fr)}.matrix-table-heading{background:var(--lz-surface-subtle,#f8f6fd);font-weight:600}.matrix-table-heading>span{padding:12px 15px}.matrix-table-heading>span+span,.matrix-records{border-left:1px solid var(--lz-border,#e8e0f0)}.matrix-row{border-top:1px solid var(--lz-border,#e8e0f0)}.matrix-point{padding:18px 14px;min-width:0}.point-name{border:0;background:none;text-align:left;color:var(--lz-text-strong,#39265d);font-weight:600!important;padding:0;overflow-wrap:anywhere}.point-state{display:block;color:var(--lz-text-secondary,#81748e);font-size:13px;margin-top:6px}.point-links{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px;color:var(--lz-brand-strong,#7252c3);font-size:13px}.point-links button,.text-action{display:inline-flex;align-items:center;gap:2px;border:0;padding:0;background:none;color:var(--lz-brand-strong,#7252c3)}.point-links button{font-size:13px}.matrix-records{display:flex;align-items:center;align-content:center;gap:9px;flex-wrap:wrap;padding:12px 14px;min-width:0}.attempt-tile{display:flex;flex-direction:column;align-items:center;gap:3px;flex:0 0 105px;max-width:100%;padding:9px 6px;border:1px solid transparent;border-radius:8px;background:#f2f2f7;color:#77768b;transition:border-color .15s,box-shadow .15s}.attempt-tile.correct{background:#edf8f0;color:#246e40}.attempt-tile.incorrect{background:#fff0f2;color:#b73449}.attempt-tile.selected{border-color:var(--lz-brand,#7654ce);box-shadow:0 0 0 2px var(--lz-brand-soft,#f4effc)}.attempt-heading{color:var(--lz-text-strong,#39265d);font-size:13px}.attempt-tile strong{display:flex;align-items:center;gap:5px;font-size:15px;font-weight:600}.attempt-support,.attempt-tile time{font-size:12px;color:#716a80}.matrix-empty-row{color:var(--lz-text-secondary,#81748e);margin-right:12px}.matrix-empty{padding:30px 18px;color:var(--lz-text-secondary,#81748e)}.matrix-footer{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap;align-items:center;margin-top:16px;font-size:13px;color:var(